var sleepCheckInterval
var lastSleepCheck = false
var lastAwake = 0
var SLEEP_CHECK_INTERVAL = 10e3
var NUM_MISSABLE_INTERVALS = 3
var EE = require('events')
var emitter = new EE()

module.exports = function (cb) {
  emitter.on('wakeup', cb)

  if (!sleepCheckInterval) {
    // setup interval
    sleepCheckInterval = setInterval(function () {
      var t = Date.now()
      var hr = process.hrtime()
      var awake = hr[0] * 1e3 + hr[1] / 1e6
      var gap = t - lastSleepCheck
      var suspended = process.platform === 'win32' ? gap : gap - (awake - lastAwake)
      if (lastSleepCheck && gap > SLEEP_CHECK_INTERVAL*NUM_MISSABLE_INTERVALS && suspended > SLEEP_CHECK_INTERVAL*(NUM_MISSABLE_INTERVALS-1))
        emitter.emit('wakeup')
      lastSleepCheck = t
      lastAwake = awake
    }, SLEEP_CHECK_INTERVAL)
  }
  
  // unreference the timer so that the program can close
  if (sleepCheckInterval.unref)
    sleepCheckInterval.unref()

  return sleepCheckInterval
}
